function SelectMenu({icon:Icon,value,options,onChange,className=''}){const[open,setOpen]=useState(false);return <div className={`select-menu ${open?'is-open':''} ${className}`}><button className="select-menu-trigger" type="button" aria-expanded={open} onClick={()=>setOpen(!open)}>{Icon&&<Icon size={15}/>}<span>{value}</span><ChevronDown size={14}/></button>{open&&<><button className="select-menu-dismiss" aria-label="Close options" onClick={()=>setOpen(false)}/><div className="select-menu-popover">{options.map(option=><button type="button" key={option} className={option===value?'selected':''} onClick={()=>{onChange(option);setOpen(false)}}>{option===value?<Check size={14}/>:<span className="select-menu-check"/>}<span>{option}</span></button>)}</div></>}</div>}
